package org.beyondlight;
import java.util.*;
/** SI base-dimension exponent algebra in order kg,m,s,A,K,mol,cd. */
public final class Dimensions {
 public record D(double[] e){public D{if(e.length!=7)throw new IllegalArgumentException("seven SI dimensions required");e=e.clone();}public boolean same(D b){for(int i=0;i<7;i++)if(Math.abs(e[i]-b.e[i])>1e-10)return false;return true;}D plus(D b){double[] x=e.clone();for(int i=0;i<7;i++)x[i]+=b.e[i];return new D(x);}D minus(D b){double[] x=e.clone();for(int i=0;i<7;i++)x[i]-=b.e[i];return new D(x);}D scale(double n){double[]x=e.clone();for(int i=0;i<7;i++)x[i]*=n;return new D(x);}public String toString(){String[] names={"kg","m","s","A","K","mol","cd"};StringJoiner j=new StringJoiner(" ");for(int i=0;i<7;i++)if(Math.abs(e[i])>1e-10)j.add(names[i]+"^"+e[i]);return j.length()==0?"1":j.toString();}}
 private static final D Z=new D(new double[7]); private Dimensions(){}
 public static D parse(String s){return switch(s.trim().toLowerCase()){case "1","dimensionless"->Z;case "mass","kg"->base(0);case "length","m"->base(1);case "time","s"->base(2);case "current","ampere"->base(3);case "temperature","kelvin","k"->base(4);case "amount","mol"->base(5);case "luminous_intensity","cd"->base(6);case "velocity","speed","m/s"->base(1).minus(base(2));case "acceleration","m/s2"->base(1).minus(base(2).scale(2));case "force","n"->base(0).plus(base(1)).minus(base(2).scale(2));case "energy","j"->base(0).plus(base(1).scale(2)).minus(base(2).scale(2));case "power","w"->base(0).plus(base(1).scale(2)).minus(base(2).scale(3));case "pressure","pa"->base(0).minus(base(1)).minus(base(2).scale(2));case "charge","c"->base(3).plus(base(2));case "voltage","volt","v"->base(0).plus(base(1).scale(2)).minus(base(2).scale(3)).minus(base(3));case "resistance","ohm"->base(0).plus(base(1).scale(2)).minus(base(2).scale(3)).minus(base(3).scale(2));case "frequency","hz"->base(2).scale(-1);case "magnetic_field","tesla"->base(0).minus(base(2).scale(2)).minus(base(3));default->throw new IllegalArgumentException("unknown dimension token: "+s);};}
 private static D base(int i){double[] a=new double[7];a[i]=1;return new D(a);}
 public static D of(Symbolic.Node n,Map<String,D> vars){if(n.op().equals("num"))return Z;if(n.op().equals("var")){if(n.atom().equals("pi")||n.atom().equals("e"))return Z;if(!vars.containsKey(n.atom()))throw new IllegalArgumentException("dimension missing for "+n.atom());return vars.get(n.atom());}D a=of(n.left(),vars);if(n.op().equals("neg"))return a;if(n.right()==null){if(Set.of("sin","cos","ln","exp").contains(n.op())&&!a.same(Z))throw new IllegalArgumentException(n.op()+" requires a dimensionless argument, got "+a);if(n.op().equals("sqrt"))return a.scale(.5);return Z;}D b=of(n.right(),vars);return switch(n.op()){case "+","-"->{if(!a.same(b))throw new IllegalArgumentException("cannot "+(n.op().equals("+")?"add":"subtract")+" dimensions "+a+" and "+b);yield a;}case "*"->a.plus(b);case "/"->a.minus(b);case "^"->{if(!b.same(Z))throw new IllegalArgumentException("exponent must be dimensionless");try{yield a.scale(Double.parseDouble(n.right().atom()));}catch(Exception e){if(a.same(Z))yield Z;throw new IllegalArgumentException("dimensioned base requires a numeric exponent");}}default->throw new IllegalArgumentException("unsupported dimension operation "+n.op());};}
 public static boolean equationBalanced(String lhs,String rhs,Map<String,D> vars){D a=of(Symbolic.parse(lhs),vars),b=of(Symbolic.parse(rhs),vars);if(!a.same(b))throw new IllegalArgumentException("equation sides differ: left ["+a+"] right ["+b+"]");return true;}
}
